          urlDisplayBox.style.borderRadius = '5px';
          urlDisplayBox.style.zIndex = '10000';
          urlDisplayBox.style.fontSize = '12px';
          urlDisplayBox.style.wordWrap = 'break-word';
          urlDisplayBox.textContent = `${window.location.href}`;

          // close button
