/*
 * for managing event listeners centrally
 */
class EventRegistry {
  constructor() {
    /** example: { ele1: [ { eventName: 'click', callback: fn1, options: { capture: true } } ] } */
    this.eventListeners = new Map();
  }

  addEventListener(element, eventName, callback, options = {}, once = true) {
    if (!this.eventListeners.has(element)) {
      this.eventListeners.set(element, []);
    }

    // Check if the event listener already exists
    const existingListeners = this.eventListeners.get(element);
    const listenerExists = existingListeners.some(
      listener =>
        listener.eventName === eventName &&
        listener.callback === callback &&
        JSON.stringify(listener.options) === JSON.stringify(options)
    );

    if (listenerExists) {
      console.warn(`Event listener for '${eventName}' already exists on this element.`);
      return;
    }

    this.eventListeners.get(element).push({ eventName, callback, options });
    element.addEventListener(eventName, callback, options);
  }

  removeEventListener(element, eventName, callback, options = {}) {
    if (this.eventListeners.has(element)) {
      const listeners = this.eventListeners.get(element);
      const index = listeners.findIndex(
        listener =>
          listener.eventName === eventName &&
          listener.callback === callback &&
          JSON.stringify(listener.options) === JSON.stringify(options)
      );

      if (index !== -1) {
        listeners.splice(index, 1); // remove the listener from the array
        element.removeEventListener(eventName, callback, options);
      }

      if (listeners.length === 0) {
        this.eventListeners.delete(element);
      }
    }
  }

  removeAllEventListeners() {
    this.eventListeners.forEach((listeners, element) => {
      listeners.forEach(({ eventName, callback, options }) => {
        element.removeEventListener(eventName, callback, options);
      });
    });

    this.eventListeners.clear();
  }

  /* for debugging */
  dump() {
    this.eventListeners.forEach((listeners, element) => {
      console.log(element);
      listeners.forEach(({ eventName, callback, options }, index) => {
        console.log(`    ${index}: ${eventName}`);
      });
    });
  }
}


